namespace HakutaiKagami.Core.Contracts;
public sealed record SupplyTerms(EntityId Owner,EntityId Custodian,EntityId Army,EntityId Site,EntityId Basis,long Capacity,long DepotInitial);
public sealed record SupplyMove(EntityId Id,bool Loading,long Amount,long At,DispatchLocation Location);
public sealed record SupplyUse(long From,long Until,int Soldiers,long Consumed);
public sealed record SupplySortie(long From,long? Until);
public sealed record SupplyState(SupplyTerms Terms,SupplyMove[] Moves,SupplyUse[] Uses,SupplySortie[] Sorties);
public static class FieldSupply
{
    public const string Ruleset="created-retainer-supply-v1",Contract="house-owned-mobile-lot-person-seconds-coalesced-atomic-local-handover-v1",Unit="ration-person-second";
    public static readonly EntityId Depot=new("lot:field-supply-depot"),Carry=new("lot:field-supply-carry"),Basis=new("basis:field-supply");
    public const long PersonDay=86400,Capacity=100*PersonDay*2,Initial=100*PersonDay*10;
    public static bool Enabled(ContractWorld w)=>w.Definitions.Ruleset==Ruleset||FieldPresence.Enabled(w);
    public static ContractWorld Create(string name="作成武将",ulong seed=20261020){var w=EngagementMission.Create(name,seed);w.WorldId=new("world:"+Ruleset);w.Definitions=w.Definitions with{Id=new("scenario:"+Ruleset),Ruleset=Ruleset,AuthorityBases=[..w.Definitions.AuthorityBases,new(Basis,"架空演習の主家兵糧の携行・使用・返還許可。私有化・遠隔補充不可")]};w.Supply=new(new(RetainerStart.House,w.PlayerControl,CreatedCampaign.Army,ContractFixture.Castle,Basis,Capacity,Initial),[],[],[]);w.ResourceLots=[..w.ResourceLots,new(Depot,"rice",RetainerStart.House,RetainerStart.House,ContractFixture.Castle,Unit,Initial,Initial,0),new(Carry,"rice",RetainerStart.House,w.PlayerControl,ContractFixture.Castle,Unit,0,0,0,w.PlayerControl)];w.Definitions=w.Definitions with{Version=RegionalBattle.Version(w)};ContractValidation.Validate(w);return w;}
    public static ResourceLot Carried(ContractWorld w)=>w.ResourceLots.Single(l=>l.Id==Carry);
    public static bool AtDepot(ContractWorld w)=>Enabled(w)&&!FieldPresence.PlayerDeployed(w)&&w.Locations.Any(l=>l.Actor==w.PlayerControl&&l.Kind==LocationKind.AtSite&&l.Site==w.Supply!.Terms.Site);
    public static void Transition(ContractWorld w,bool active){if(!Enabled(w))return;var s=w.Supply!;if(active){if(Carried(w).Quantity<=0)throw new InvalidDataException("携行兵糧を積載してください");w.Supply=s with{Sorties=[..s.Sorties,new(w.ElapsedSeconds,null)]};}else{var last=s.Sorties.Last();w.Supply=s with{Sorties=[..s.Sorties[..^1],last with{Until=w.ElapsedSeconds}]};}}
    public static void Tick(ContractWorld w,long from)
    {
        if(!Enabled(w)||!FieldPresence.PlayerDeployed(w)||w.ElapsedSeconds==from)return;
        var carry=Carried(w);int strength=w.Region!.Units.Where(u=>u.Commander==w.PlayerControl).Sum(u=>u.Soldiers);long until=w.ElapsedSeconds,required=checked(strength*(until-from)),amount=Math.Min(required,carry.Quantity);var uses=w.Supply!.Uses;
        void Append(SupplyUse next){if(next.Until<=next.From)return;if(uses.LastOrDefault() is {} last&&last.Until==next.From&&last.From>=w.Supply.Sorties.Last().From&&last.Soldiers==next.Soldiers&&((last.Consumed==0&&next.Consumed==0)||(last.Consumed==checked(last.Soldiers*(last.Until-last.From))&&next.Consumed==checked(next.Soldiers*(next.Until-next.From)))))uses=[..uses[..^1],last with{Until=next.Until,Consumed=checked(last.Consumed+next.Consumed)}];else uses=[..uses,next];}
        if(strength==0||amount==required)Append(new(from,until,strength,amount));
        else{long full=Math.Min(until-from,carry.Quantity/strength),fullEnd=from+full;Append(new(from,fullEnd,strength,checked(full*strength)));long remainder=carry.Quantity-checked(full*strength);if(remainder>0&&fullEnd<until){Append(new(fullEnd,fullEnd+1,strength,remainder));fullEnd++;}Append(new(fullEnd,until,strength,0));}
        w.ResourceLots=w.ResourceLots.Select(l=>l.Id==Carry?l with{Quantity=l.Quantity-amount,Revision=w.CommitSequence}:l).ToArray();w.Supply=w.Supply with{Uses=uses};
    }
    public static long Net(ContractWorld w,EntityId lot){if(!Enabled(w))return 0;long moved=w.Supply!.Moves.Sum(m=>m.Loading?m.Amount:-m.Amount);return lot==Depot?-moved:lot==Carry?checked(moved-w.Supply.Uses.Sum(u=>u.Consumed)):0;}
    public static LocationState Location(ContractWorld w,ResourceLot lot)=>w.Locations.Single(l=>l.Actor==(lot.MobileHolder??throw new InvalidDataException("Fixed lots use their site, not a fictional actor location")));
    public static void Validate(ContractWorld w){if(!Enabled(w))return;var s=w.Supply??throw new InvalidDataException("Missing supply module");if(s.Terms!=new SupplyTerms(RetainerStart.House,w.PlayerControl,CreatedCampaign.Army,ContractFixture.Castle,Basis,Capacity,Initial)||!w.Definitions.AuthorityBases.Any(b=>b.Id==Basis))throw new InvalidDataException("Invalid supply custody");
        foreach(var id in new[]{Depot,Carry}){var l=w.ResourceLots.Single(l=>l.Id==id);if(l.Kind!="rice"||l.Owner!=s.Terms.Owner||l.Holder!=(id==Carry?w.PlayerControl:s.Terms.Owner)||l.Site!=s.Terms.Site||l.Unit!=Unit||l.InitialQuantity!=(id==Carry?0:Initial)||l.MobileHolder!=(id==Carry?w.PlayerControl:(EntityId?)null))throw new InvalidDataException("Invalid resource lot custody");}
        if(w.Transfers.Any(t=>t.FromLot==Carry||t.ToLot==Carry||t.FromLot==Depot||t.ToLot==Depot)||w.ResourceLots.Any(l=>l.MobileHolder!=null&&l.Id!=Carry))throw new InvalidDataException("Unregistered mobile inventory movement");
        if(s.Moves.Select(m=>m.Id).Distinct().Count()!=s.Moves.Length||s.Moves.Any(m=>!EntityId.IsValid(m.Id.Value)||m.Amount<=0||m.At<0||m.At>w.ElapsedSeconds))throw new InvalidDataException("Invalid stock movement");
        foreach(var m in s.Moves){var l=m.Location;if(l!=new DispatchLocation(w.PlayerControl,LocationKind.AtSite,s.Terms.Site,null,0,0,null,null,null,null)||RegionalCampaign.RoadActorPointAt(w,w.PlayerControl,m.At)!=BranchRoutes.GraphNodes(w).Single(n=>n.Id=="castle").Position)throw new InvalidDataException("Handover lacks physical local custody");}
        if(s.Sorties.Any(t=>t.From<0||t.From>w.ElapsedSeconds||t.Until is {} end&&(end<t.From||end>w.ElapsedSeconds))||s.Sorties.Select((t,i)=>i>0&&(s.Sorties[i-1].Until==null||s.Sorties[i-1].Until>t.From)).Any(b=>b)||s.Sorties.Count(t=>t.Until==null)!=(FieldPresence.PlayerDeployed(w)?1:0))throw new InvalidDataException("Invalid supply sortie history");
        foreach(var use in s.Uses){int strength=w.Region!.Units.Where(u=>CareerMilitary.Enabled(w)?FieldWorld.UnitIds.Contains(u.Id):u.Commander==w.PlayerControl).Sum(u=>u.InitialSoldiers-w.Region!.Losses.Where(l=>l.Unit==u.Id&&l.At<=use.From).Sum(l=>l.Soldiers));if(use.From<0||use.Until<=use.From||use.Until>w.ElapsedSeconds||use.Soldiers!=strength||use.Consumed<0||use.Consumed>checked(use.Soldiers*(use.Until-use.From))||!s.Sorties.Any(t=>t.From<=use.From&&use.Until<=(t.Until??w.ElapsedSeconds))||w.Region!.Losses.Any(l=>w.Region!.Units.Any(u=>u.Id==l.Unit&&u.Commander==w.PlayerControl)&&l.At>use.From&&l.At<use.Until))throw new InvalidDataException("Invalid consumption interval");}
        if(s.Uses.Select((u,i)=>i>0&&s.Uses[i-1].Until>u.From).Any(b=>b))throw new InvalidDataException("Overlapping consumption");foreach(var t in s.Sorties)if(s.Uses.Where(u=>u.From>=t.From&&u.Until<=(t.Until??w.ElapsedSeconds)).Sum(u=>u.Until-u.From)!=(t.Until??w.ElapsedSeconds)-t.From)throw new InvalidDataException("Supply time missing or duplicated");
        long depot=Initial,carry=0;var events=s.Moves.Select(m=>(At:m.At,Order:1,Move:(SupplyMove?)m,Use:(SupplyUse?)null)).Concat(s.Uses.Select(u=>(At:u.Until,Order:0,Move:(SupplyMove?)null,Use:(SupplyUse?)u))).OrderBy(e=>e.At).ThenBy(e=>e.Order);foreach(var e in events){if(e.Move is {} m){if(s.Sorties.Any(t=>t.From<m.At&&m.At<(t.Until??long.MaxValue)))throw new InvalidDataException("Remote stock handover");long delta=m.Loading?m.Amount:-m.Amount;depot=checked(depot-delta);carry=checked(carry+delta);if(depot<0||carry<0||carry>Capacity)throw new InvalidDataException("Overallocated supply");}else if(e.Use is {} u){long expected=Math.Min(carry,checked(u.Soldiers*(u.Until-u.From)));if(u.Consumed!=expected)throw new InvalidDataException("Consumption does not match inventory");carry-=expected;}}
        if(depot!=w.ResourceLots.Single(l=>l.Id==Depot).Quantity||carry!=Carried(w).Quantity)throw new InvalidDataException("Supply conservation failure");
    }
}
